package com.course.platform.service.impl;

import com.course.platform.domain.dto.CoursePrivateOrderFact;
import com.course.platform.domain.entity.CoursePrivateContractTerm;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

/** 消费资格以原订单及可信时间为准，期末和结算截止不能混成同一购买期限。 */
class CoursePrivateConsumptionPolicyTest {
    LocalDateTime start=LocalDateTime.parse("2026-10-01T10:00:00"),end=start.plusDays(30),deadline=end.plusDays(7);
    CoursePrivateContractTerm term(){var term=new CoursePrivateContractTerm();term.setId(10L);term.setContractId(3L);term.setUserId(7L);term.setPlatformId(9L);term.setVersionId(2L);term.setOperationsMode("PERFORMANCE_RENEWAL");term.setStartAt(start);term.setEndAt(end);term.setEffectiveFixedPrice(new BigDecimal("7.20"));term.setRenewalTarget(new BigDecimal("14.40"));return term;}
    CoursePrivateOrderFact fact(long id){var row=new CoursePrivateOrderFact();row.setId(id);row.setOrderId(id);row.setOrderNo("order_"+id);row.setTermId(10L);row.setContractId(3L);row.setUserId(7L);row.setPlatformId(9L);row.setOrderedAmount(new BigDecimal("7.20"));row.setPaidAt(start.plusHours(1));row.setOrderAmount(new BigDecimal("7.20"));row.setOrderUserId(7L);row.setOrderPlatformId(9L);row.setOrderContractId(3L);row.setOrderWalletId(5L);row.setOrderTermId(10L);row.setOrderPlanVersionId(2L);row.setOrderOperationsMode("PERFORMANCE_RENEWAL");row.setOrderPriceSource("PRIVATE");row.setOrderPaymentSource("COURSE_WALLET");row.setOrderStatus(2);row.setOriginalDebitExists(true);row.setRefundExists(false);row.setRefundAmount(BigDecimal.ZERO);row.setFulfilledAt(start.plusHours(2));row.setFulfillmentSource("SELF_OPERATED_COMPLETED");return row;}
    CoursePrivateConsumptionPolicy.Assessment assess(CoursePrivateContractTerm term,List<CoursePrivateOrderFact> rows,LocalDateTime now){return CoursePrivateConsumptionPolicy.assess(term,5L,rows,now,deadline);}
    @Test void completedPaidOrdersQualifyButNeverFinalizeInsideActivePeriod(){var value=assess(term(),List.of(fact(1),fact(2)),start.plusDays(1));assertEquals(new BigDecimal("14.40"),value.amount());assertEquals(2,value.orderCount());assertEquals("QUALIFIED",value.result());assertFalse(value.finalizable());}
    @Test void zeroOrdersCannotPrematurelyCloseAnActiveTerm(){var value=assess(term(),List.of(),start);assertFalse(value.finalizable());assertEquals("PENDING",value.result());}
    @Test void allTerminalOrdersCanFinalizeAtPurchaseEnd(){var value=assess(term(),List.of(fact(1)),end);assertTrue(value.finalizable());assertEquals("NOT_QUALIFIED",value.result());}
    @Test void pendingOrdersWaitUntilDeadlineWithoutPurchaseExtension(){var row=fact(1);row.setOrderStatus(1);row.setFulfilledAt(null);row.setFulfillmentSource(null);var before=assess(term(),List.of(row),end.plusDays(1));assertEquals(1,before.pendingCount());assertFalse(before.finalizable());assertTrue(assess(term(),List.of(row),deadline).finalizable());}
    @Test void exactCompletionAtDeadlineCountsButOneSecondLaterDoesNot(){var row=fact(1);row.setFulfilledAt(deadline);assertEquals(new BigDecimal("7.20"),assess(term(),List.of(row),deadline).amount());row.setFulfilledAt(deadline.plusSeconds(1));assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),deadline.plusSeconds(1)).amount());}
    @Test void verifiedCompletionAfterEndWithinGraceBelongsToOriginalTerm(){var row=fact(1);row.setFulfilledAt(end.plusDays(3));assertEquals(new BigDecimal("7.20"),assess(term(),List.of(row),end.plusDays(4)).amount());}
    @Test void paymentAtOriginalEndIsExcluded(){var row=fact(1);row.setPaidAt(end);row.setFulfilledAt(end.plusHours(1));assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),end.plusDays(1)).amount());}
    @Test void archivedCompletionStillCountsUntilRealRefund(){var row=fact(1);row.setArchived(true);assertEquals(new BigDecimal("7.20"),assess(term(),List.of(row),end).amount());row.setRefundExists(true);row.setRefundAmount(new BigDecimal("7.20"));row.setOrderRefundedAt(end);var value=assess(term(),List.of(row),end);assertEquals(new BigDecimal("0.00"),value.amount());assertEquals("REFUNDED",value.rows().get(0).status());}
    @Test void refundLedgerDominatesAnUpstreamOverwriteBackToCompleted(){var row=fact(1);row.setRefundExists(true);row.setRefundAmount(new BigDecimal("7.20"));assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),end).amount());}
    @Test void wrongProductWalletTermAndMissingDebitRequireReview(){for(String field:List.of("product","wallet","term","debit")){var row=fact(1);switch(field){case "product"->row.setOrderPlatformId(99L);case "wallet"->row.setOrderWalletId(99L);case "term"->row.setOrderTermId(99L);case "debit"->row.setOriginalDebitExists(false);}var value=assess(term(),List.of(row),end);assertEquals("REVIEW_REQUIRED",value.result());assertEquals(new BigDecimal("0.00"),value.amount());}}
    @Test void statusAloneAndUnknownCompletionSourceCannotProduceConsumption(){var row=fact(1);row.setFulfilledAt(null);row.setFulfillmentSource(null);assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),end).amount());row.setFulfilledAt(start.plusHours(2));row.setFulfillmentSource("client_input");assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),end).amount());}
    @Test void confirmedUpperBoundIsEvidenceWithoutInventingActualTime(){var row=fact(1);row.setFulfilledAt(null);row.setFulfillmentSource(null);row.setCompletionConfirmedAt(end.plusDays(1));row.setCompletionConfirmationSource("UPSTREAM_STATUS");var value=assess(term(),List.of(row),end.plusDays(2));assertEquals(new BigDecimal("7.20"),value.amount());assertNull(value.rows().get(0).completedAt());assertEquals("CONFIRMED_BEFORE_DEADLINE",value.rows().get(0).basis());}
    @Test void lateObservationCannotPretendToHaveCompletedBeforeDeadline(){var row=fact(1);row.setFulfilledAt(null);row.setFulfillmentSource(null);row.setCompletionConfirmedAt(deadline.plusSeconds(1));row.setCompletionConfirmationSource("UPSTREAM_STATUS");assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),deadline.plusDays(1)).amount());}
    @Test void cancelledAndFailedOrdersNeverQualify(){for(int status:List.of(3,4,6)){var row=fact(1);row.setOrderStatus(status);assertEquals(new BigDecimal("0.00"),assess(term(),List.of(row),end).amount());}}
    @Test void monetaryMismatchAndUnsupportedPartialRefundRequireReview(){var row=fact(1);row.setOrderAmount(new BigDecimal("9"));assertEquals("REVIEW_REQUIRED",assess(term(),List.of(row),end).result());row=fact(1);row.setRefundExists(true);row.setRefundAmount(new BigDecimal("1"));assertEquals("REVIEW_REQUIRED",assess(term(),List.of(row),end).result());}
    @Test void duplicateOrderCannotCountTwice(){var row=fact(1);assertThrows(RuntimeException.class,()->assess(term(),List.of(row,row),end));}
    @Test void exactTimeCannotContradictEarlierVerifiedCompletionUpperBound(){var row=fact(1);row.setCompletionConfirmedAt(start.plusHours(1));row.setCompletionConfirmationSource("UPSTREAM_STATUS");assertEquals("REVIEW_REQUIRED",assess(term(),List.of(row),end).result());}
}
